	/** A child stays visible to its real query owner until its resource outcome reaches that owner. */
	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2 })
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void parentCloseWaitsForChildResourceSettlementAndReceivesItsOriginalFailure(int failureKind) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			AtomicReference<NativeExecutionContext> root = new AtomicReference<>();
			AtomicReference<NativeExecutionContext> child = new AtomicReference<>();
			AtomicReference<LmdbNativeMorselExecutor<Object>> execution = new AtomicReference<>();
			AtomicReference<Thread> worker = new AtomicReference<>();
			AtomicReference<Thread> closer = new AtomicReference<>();
			AtomicReference<Throwable> workerFailure = new AtomicReference<>();
			AtomicReference<Throwable> closeFailure = new AtomicReference<>();
			AtomicInteger rootCloses = new AtomicInteger();
			AtomicInteger childCloses = new AtomicInteger();
			AtomicInteger exchangeCloses = new AtomicInteger();
			AtomicBoolean childResourcesFinished = new AtomicBoolean();
			CountDownLatch bodyReady = new CountDownLatch(1);
			CountDownLatch releaseBody = new CountDownLatch(1);
			CountDownLatch resourceEntered = new CountDownLatch(1);
			CountDownLatch releaseResource = new CountDownLatch(1);
			CountDownLatch closerEntered = new CountDownLatch(1);
			CountDownLatch closerReturned = new CountDownLatch(1);
			Throwable failure = failureKind == 1 ? new IllegalStateException("child native resource")
					: failureKind == 2 ? new AssertionError("child native resource") : null;
			try {
				fixture.block(row -> {
					NativeExecutionContext parent = row.evaluationScope().executionContext();
					root.set(parent);
					// This is the real child constructor used when a nested evaluation has a distinct catalog.
					NativeExecutionContext owner = new NativeExecutionContext(parent);
					child.set(owner);
					var rootLease = parent.retainLease();
					var childLease = owner.retainLease();
					var morsel = new LmdbNativeMorselExecutor<Object>(1, 1, row.cancellation, owner);
					execution.set(morsel);
					parent.nativeState(new Object(), () -> (AutoCloseable) () -> {
						assertThat(childResourcesFinished).as("child cleanup precedes root resources").isTrue();
						rootCloses.incrementAndGet();
					});
					owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
						childCloses.incrementAndGet();
						resourceEntered.countDown();
						try {
							parent.close(); // Its exact child notification defers, rather than waiting for itself.
							awaitNativeTestGate(releaseResource);
							if (failure != null) {
								raise(failure);
							}
						} finally {
							childResourcesFinished.set(true);
						}
					});
					owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
						exchangeCloses.incrementAndGet();
						morsel.close();
					});
					NativeFilterLease selected = new NativeFilterLease();
					drainValues(row, selected.borrow(fixture.recording(new TrackingFilter())), 8, false);
					selected.commit();
					try (var registration = QueryExecutionContext.activateReplaySafepoint(() -> {
					}, () -> () -> () -> {
						childLease.exhausted();
						childLease.close();
						rootLease.exhausted();
						rootLease.close();
					})) {
						morsel.start(command -> {
							Thread thread = Thread.ofVirtual()
									.uncaughtExceptionHandler((ignored, problem) -> workerFailure.set(problem))
									.unstarted(command);
							worker.set(thread);
							thread.start();
						}, (index, running) -> {
							bodyReady.countDown();
							awaitNativeTestGate(releaseBody);
						});
						assertThat(bodyReady.await(30, TimeUnit.SECONDS)).isTrue();
					}
					owner.close();
				});
				releaseBody.countDown();
				assertThat(resourceEntered.await(30, TimeUnit.SECONDS)).isTrue();
				assertThat(root.get().isClosed()).as("child resource cleanup still owns query settlement").isFalse();
				assertThat(rootCloses).hasValue(0);
				assertThat(fixture.statistics.typed).as("no terminal publication before child cleanup").isEmpty();
				closer.set(Thread.ofVirtual().start(() -> {
					closerEntered.countDown();
					try {
						root.get().close();
					} catch (Throwable problem) {
						closeFailure.set(problem);
					} finally {
						closerReturned.countDown();
					}
				}));
				assertThat(closerEntered.await(30, TimeUnit.SECONDS)).isTrue();
				awaitNativeThreadState(closer.get(), Thread.State.WAITING, closerReturned);
				assertThat(rootCloses).hasValue(0);
				assertThat(fixture.statistics.typed).isEmpty();
				releaseResource.countDown();
				assertThat(closerReturned.await(30, TimeUnit.SECONDS)).isTrue();
				joinNativeTestThread(worker.get());
				joinNativeTestThread(closer.get());
				if (failure == null) {
					execution.get().finish();
					assertThat(workerFailure.get()).isNull();
					assertThat(closeFailure.get()).isNull();
					assertComplete(fixture.statistics, 8L, 0L);
				} else {
					assertThat(workerFailure.get()).isSameAs(failure);
					assertThat(closeFailure.get()).isSameAs(failure);
					assertThatThrownBy(() -> execution.get().finish()).isSameAs(failure);
					assertIncomplete(fixture.statistics);
					assertThat(fixture.statistics.typed).hasSize(1).allSatisfy(outcome -> {
						assertThat(outcome.passedCount()).isEqualTo(8L);
						assertThat(outcome.filteredCount()).isZero();
					});
				}
				assertThat(root.get().isClosed()).isTrue();
				assertThat(child.get().isClosed()).isTrue();
				assertThat(rootCloses).hasValue(1);
				assertThat(childCloses).hasValue(1);
				assertThat(exchangeCloses).hasValue(1);
				root.get().close();
				child.get().close();
				execution.get().close();
				assertThat(rootCloses).hasValue(1);
				assertThat(childCloses).hasValue(1);
				assertThat(exchangeCloses).hasValue(1);
			} finally {
				releaseBody.countDown();
				releaseResource.countDown();
				for (Thread thread : new Thread[] { worker.get(), closer.get() }) {
					if (thread != null && thread.isAlive()) {
						thread.interrupt();
						joinNativeTestThread(thread);
					}
				}
			}
		}
	}

	/** The real waiting owner, rather than a worker Future, must observe deferred resource cleanup failure. */
	@ParameterizedTest
	@CsvSource({ "false,false,false", "true,false,false", "false,true,false", "true,true,false",
			"false,false,true", "true,false,true", "false,true,true", "true,true,true" })
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void realMorselWaiterAndRacingContextCloseObserveTheTerminalResourceFailure(
			boolean error, boolean closeApi, boolean failScope) throws Exception {
		try (Fixture fixture = new Fixture(directory)) {
			AtomicReference<NativeExecutionContext> context = new AtomicReference<>();
			AtomicReference<LmdbNativeMorselExecutor<Object>> execution = new AtomicReference<>();
			AtomicReference<Thread> worker = new AtomicReference<>();
			AtomicReference<Thread> waiter = new AtomicReference<>();
			AtomicReference<Thread> closer = new AtomicReference<>();
			AtomicReference<Throwable> workerFailure = new AtomicReference<>();
			AtomicReference<Throwable> waiterFailure = new AtomicReference<>();
			AtomicReference<Throwable> closerFailure = new AtomicReference<>();
			AtomicInteger resourceCloses = new AtomicInteger();
			AtomicInteger exchangeCloses = new AtomicInteger();
			CountDownLatch bodyReady = new CountDownLatch(1);
			CountDownLatch releaseBody = new CountDownLatch(1);
			CountDownLatch resourceEntered = new CountDownLatch(1);
			CountDownLatch releaseResource = new CountDownLatch(1);
			CountDownLatch waiterEntered = new CountDownLatch(1);
			CountDownLatch waiterReturned = new CountDownLatch(1);
			CountDownLatch closerEntered = new CountDownLatch(1);
			CountDownLatch closerReturned = new CountDownLatch(1);
			Throwable failure = error ? new AssertionError("terminal native resource")
					: new IllegalStateException("terminal native resource");
			try {
				fixture.block(row -> {
					NativeExecutionContext owner = row.evaluationScope().executionContext();
					context.set(owner);
					var lease = owner.retainLease();
					var morsel = new LmdbNativeMorselExecutor<Object>(1, 1, row.cancellation, owner);
					execution.set(morsel);
					owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
						resourceCloses.incrementAndGet();
						resourceEntered.countDown();
						awaitNativeTestGate(releaseResource);
						if (!failScope) {
							raise(failure);
						}
					});
					owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
						exchangeCloses.incrementAndGet();
						morsel.close();
					});
					NativeFilterLease selected = new NativeFilterLease();
					drainValues(row, selected.borrow(fixture.recording(new TrackingFilter())), 8, false);
					selected.commit();
					try (var registration = QueryExecutionContext.activateReplaySafepoint(() -> {
					}, () -> () -> () -> {
						lease.exhausted();
						lease.close();
						if (failScope) {
							raise(failure);
						}
					})) {
						morsel.start(command -> {
							Thread thread = Thread.ofVirtual()
									.uncaughtExceptionHandler((ignored, problem) -> workerFailure.set(problem))
									.unstarted(command);
							worker.set(thread);
							thread.start();
						}, (index, running) -> {
							bodyReady.countDown();
							awaitNativeTestGate(releaseBody);
						});
						assertThat(bodyReady.await(30, TimeUnit.SECONDS)).isTrue();
					}
				});
				releaseBody.countDown();
				assertThat(resourceEntered.await(30, TimeUnit.SECONDS)).isTrue();
				assertThat(fixture.statistics.typed).as("resource cleanup is still pending").isEmpty();
				waiter.set(Thread.ofVirtual().start(() -> {
					waiterEntered.countDown();
					try {
						if (closeApi) {
							execution.get().close();
						} else {
							execution.get().finish();
						}
					} catch (Throwable problem) {
						waiterFailure.set(problem);
					} finally {
						waiterReturned.countDown();
					}
				}));
				assertThat(waiterEntered.await(30, TimeUnit.SECONDS)).isTrue();
				awaitNativeThreadState(waiter.get(), Thread.State.WAITING, waiterReturned);
				assertThat(waiterFailure.get()).isNull();
				closer.set(Thread.ofVirtual().start(() -> {
					closerEntered.countDown();
					try {
						context.get().close();
					} catch (Throwable problem) {
						closerFailure.set(problem);
					} finally {
						closerReturned.countDown();
					}
				}));
				assertThat(closerEntered.await(30, TimeUnit.SECONDS)).isTrue();
				awaitNativeThreadState(closer.get(), Thread.State.BLOCKED, closerReturned);
				releaseResource.countDown();
				assertThat(waiterReturned.await(30, TimeUnit.SECONDS)).isTrue();
				assertThat(closerReturned.await(30, TimeUnit.SECONDS)).isTrue();
				joinNativeTestThread(worker.get());
				joinNativeTestThread(waiter.get());
				joinNativeTestThread(closer.get());
				assertThat(waiterFailure.get()).as("actual waiting owner receives original cleanup failure")
						.isSameAs(failure);
				assertThat(closerFailure.get()).as("already racing close observes the stored outcome")
						.isSameAs(failure);
				assertThat(workerFailure.get()).isSameAs(failure);
				assertThat(resourceCloses).hasValue(1);
				assertThat(exchangeCloses).hasValue(1);
				assertIncomplete(fixture.statistics);
				assertThat(fixture.statistics.typed).hasSize(1).allSatisfy(outcome -> {
					assertThat(outcome.passedCount()).isEqualTo(8L);
					assertThat(outcome.filteredCount()).isZero();
				});
				context.get().close();
				execution.get().close();
				assertThat(resourceCloses).hasValue(1);
				assertThat(exchangeCloses).hasValue(1);
			} finally {
				releaseBody.countDown();
				releaseResource.countDown();
				for (Thread thread : new Thread[] { worker.get(), waiter.get(), closer.get() }) {
					if (thread != null && thread.isAlive()) {
						thread.interrupt();
						joinNativeTestThread(thread);
					}
				}
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	@Timeout(value = 120, unit = TimeUnit.SECONDS)
	void aWaitAdmittedBeforeCallbackRegistrationRebasesAndKeepsReportingFailurePrimary(boolean error)
			throws Exception {
		var tasks = new NativeExecutionContext.WorkerTasks(1);
		AtomicReference<Throwable> awaited = new AtomicReference<>();
		AtomicReference<Throwable> thrown = new AtomicReference<>();
		AtomicInteger nativeCloses = new AtomicInteger();
		AtomicInteger reports = new AtomicInteger();
		CountDownLatch waiting = new CountDownLatch(1);
		CountDownLatch returned = new CountDownLatch(1);
		CountDownLatch notificationEntered = new CountDownLatch(1);
		CountDownLatch releaseNotification = new CountDownLatch(1);
		Throwable primary = error ? new AssertionError("notification primary")
				: new IllegalStateException("notification primary");
		Throwable reporting = new IllegalArgumentException("cleanup consumer failure");
		Thread waiter = Thread.ofVirtual().start(() -> {
			waiting.countDown();
			try {
				tasks.await();
				awaited.set(tasks.cleanupFailure());
			} catch (InterruptedException problem) {
				Thread.currentThread().interrupt();
				awaited.set(problem);
			} finally {
				returned.countDown();
			}
		});
		Thread worker = null;
		try {
			assertThat(waiting.await(30, TimeUnit.SECONDS)).isTrue();
			awaitNativeThreadState(waiter, Thread.State.WAITING, returned);
			tasks.afterSettlement(() -> {
				notificationEntered.countDown();
				awaitNativeTestGate(releaseNotification);
				raise(primary);
			});
			worker = Thread.ofVirtual()
					.uncaughtExceptionHandler((ignored, problem) -> thrown.set(problem))
					.start(() -> {
						try (var task = tasks.enter(nativeCloses::incrementAndGet, problem -> {
							reports.incrementAndGet();
							assertThat(problem).isSameAs(primary);
							raise(reporting);
						})) {
						}
					});
			assertThat(notificationEntered.await(30, TimeUnit.SECONDS)).isTrue();
			assertThat(tasks.getCount()).as("external count includes pending notification").isEqualTo(1L);
			assertThat(tasks.await(0L, TimeUnit.NANOSECONDS)).isFalse();
			awaitNativeThreadState(waiter, Thread.State.WAITING, returned);
			releaseNotification.countDown();
			assertThat(returned.await(30, TimeUnit.SECONDS)).isTrue();
			joinNativeTestThread(worker);
			joinNativeTestThread(waiter);
			assertThat(awaited.get()).isSameAs(primary);
			assertThat(thrown.get()).isSameAs(primary);
			assertThat(primary.getSuppressed()).containsExactly(reporting);
			assertThat(reports).hasValue(1);
			assertThat(nativeCloses).hasValue(1);
			assertThat(tasks.getCount()).isZero();
			assertThat(tasks.await(0L, TimeUnit.NANOSECONDS)).isTrue();
		} finally {
			releaseNotification.countDown();
			for (Thread thread : new Thread[] { worker, waiter }) {
				if (thread != null && thread.isAlive()) {
					thread.interrupt();
					joinNativeTestThread(thread);
				}
			}
		}
	}

